import { useState } from "react";
import {
  type WahState,
  wahDevice,
} from "@/components/audio-ui/devices/wah/device";
import { createWahEngine } from "@/components/audio-ui/devices/wah/engine";
import { WahPanel } from "@/components/audio-ui/devices/wah/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useDemoSound } from "@/hooks/use-demo-source";
import { useDeviceSignal } from "@/hooks/use-device-signal";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * A wah you can plug in: its state, a panel that draws the band and its
 * travel and an engine that plays it, each its own file and none knowing the
 * others. Play the loop: the louder the hit, the higher the band.
 */
export function BlockWah() {
  const [state, setState] = useState<WahState>(() => wahDevice.defaults());
  const master = useMasterBus(MASTER_VOLUME);
  const sound = useDemoSound("groove");
  const { engine } = useDeviceLoop({
    create: createWahEngine,
    destination: master,
    sound,
    state,
  });
  const signal = useDeviceSignal(engine, wahDevice);
  return (
    <div className="rounded-xl h-full w-full min-w-0">
      <WahPanel onValueChange={setState} signal={signal} value={state} />
    </div>
  );
}
